```java
// Good code snippet: Proper use of Java API with input validation and sanitization

import java.util.Scanner;
import java.io.IOException;

public class SafeExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Good: Validate and sanitize input before processing
        String userInput = scanner.nextLine();

        // Good: Sanitize the input to prevent injection attacks
        String sanitizedInput = userInput.replaceAll("[^a-zA-Z0-9\\s]", "");

        // Good: Use a safer approach for executing commands if necessary
        try {
            ProcessBuilder processBuilder = new ProcessBuilder("echo", sanitizedInput);
            Process process = processBuilder.start();
            int exitCode = process.waitFor();
            System.out.println("Command exited with code: " + exitCode);
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}
```

