// Good code snippet: Proper use of Java API with input validation and sanitization

import java.util.Scanner;

public class SecureExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Good: Prompting the user for input and validating it helps prevent unexpected behaviors.
        System.out.println("Enter a string:");
        String input = scanner.nextLine();

        // Good: Sanitizing input by trimming whitespace helps avoid unnecessary characters causing issues.
        String sanitizedInput = input.trim();

        // Good: Providing feedback about the sanitized input ensures clarity and correctness.
        System.out.println("Sanitized input: " + sanitizedInput);
    }
}
