```java
// Extrait de code corrigé : Utilisation sécurisée de l'API Java avec gestion des erreurs et protection contre les attaques XSS
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class SecureExample {
    public static void main(String[] args) {
        try {
            URL url = new URL("http://example.com/api/data");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");

            if (conn.getResponseCode() == HttpURLConnection.HTTP_OK) {
                BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                String inputLine;
                StringBuilder content = new StringBuilder();

                while ((inputLine = in.readLine()) != null) {
                    // Échappement des caractères HTML pour éviter les attaques XSS
                    content.append("<div>").append(htmlEscape(inputLine)).append("</div>");
                }
                in.close();

                System.out.println(content.toString());
            } else {
                System.out.println("Erreur lors de la récupération des données: " + conn.getResponseMessage());
            }
        } catch (Exception e) {
            System.out.println("Une erreur s'est produite: " + e.getMessage());
        }
    }

    private static String htmlEscape(String input) {
        if (input == null) return "";
        StringBuilder escaped = new StringBuilder();
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            switch (c) {
                case '<':
                    escaped.append("&lt;");
                    break;
                case '>':
                    escaped.append("&gt;");
                    break;
                case '&':
                    escaped.append("&amp;");
                    break;
                default:
                    escaped.append(c);
            }
        }
        return escaped.toString();
    }
}
```

