// ठीक किया गया कोड स्निपेट: अनुचित उपयोग को सुधार देता है
public class SecureCode {
    public static void main(String[] args) {
        // मूल रूप से, हमें एक String प्राप्त होती है
        String input = "example.com"; // इसके बजाय, आपको इंटरनेट से प्राप्त करना चाहिए

        // इसके बजाय, हम एक URL वैधता की जांच करते हैं
        if (isValidUrl(input)) {
            System.out.println("URL is valid");
        } else {
            System.out.println("Invalid URL format");
        }
    }

    // URL वैधता की जांच करती है
    private static boolean isValidUrl(String url) {
        return url != null && url.matches("^(http|https)://[a-zA-Z0-9.-]+\\.[a-zA-Z]{2,}$");
    }
}
```

