[фрагмент кода 2]  
```java
// Хороший фрагмент кода: использование API с проверкой и безопасной обработкой

public class SecureAPIUsage {
    public static void main(String[] args) {
        String userInput = "https://example.com";
        try {
            // Безопасное использование API с проверкой URL
            fetchContent(userInput);
        } catch (Exception e) {
            System.out.println("Ошибка: " + e.getMessage());
        }
    }

    private static void fetchContent(String url) throws Exception {
        // Проверка URL перед вызовом API
        if (!isValidURL(url)) {
            throw new IllegalArgumentException("Некорректный URL");
        }

        // Реальный вызов API здесь
        System.out.println("Загружен безопасный контент с " + url);
    }

    private static boolean isValidURL(String url) {
        // Добавьте логику проверки URL по вашему усмотрению
        return url != null && url.trim().startsWith("http");
    }
}
```

