import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class SecureAPIUsage {
    public static void main(String[] args) {
        try {
            // Esempio di input sicuro, in un ambiente reale si userebbe una variabile fornita da un utente verificato
            String userInput = "userInput";

            // Codifica URL per evitare attacchi come SQL injection o XSS
            String encodedUserInput = java.net.URLEncoder.encode(userInput, "UTF-8");

            URL url = new URL("https://api.example.com/data?query=" + encodedUserInput);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            reader.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

